('anac', '1766ead6-439a-4978-ad43-03a2a4cbdff2', 'Conhecimentos Técnicos', null, 'OS PARÂMETROS ADOTADOS PARA O NÍVEL DO MAR, QUE CONSTITUEM A ATMOSFERA PADRÃO, SÃO:', null, '[{"letra": "A", "texto": "pressão, temperatura e densidade", "imagem_url": null}, {"letra": "B", "texto": "altitude, pressão e fluídos", "imagem_url": null}, {"letra": "C", "texto": "mecânica dos gases e densidade", "imagem_url": null}, {"letra": "D", "texto": "temperaturas, fluidos e pressão", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '177ee50d-a40a-4d85-a96c-f8fce168b253', 'Conhecimentos Técnicos', null, 'COMO SE CLASSIFICAM OS AVIÕES TERRESTRES, QUANTO A DISPOSIÇÃO DAS RODAS?', null, '[{"letra": "A", "texto": "fixo e retrátil", "imagem_url": null}, {"letra": "B", "texto": "fixo e escamoteável", "imagem_url": null}, {"letra": "C", "texto": "convencional e triciclo", "imagem_url": null}, {"letra": "D", "texto": "convencional e retrátil", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '178c100d-bf1c-4139-81eb-6140151a2e36', 'Conhecimentos Técnicos', null, 'OS EQUIPAMENTOS PARA COMBATE A FOCOS DE INCÊNDIO, EXISTENTES A BORDO, SÃO: EXTINTORES,', null, '[{"letra": "A", "texto": "óculos contra fumaça e máscaras oronasais", "imagem_url": null}, {"letra": "B", "texto": "garrafas de oxigênio, luvas de amianto e óculos contra fumaça", "imagem_url": null}, {"letra": "C", "texto": "luvas de amianto, capuzes anti-fumaça e machadinha", "imagem_url": null}, {"letra": "D", "texto": "oxigênio terapêutico e machadinha", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '1793247b-aefc-4b80-b48a-276005b11f6b', 'Conhecimentos Técnicos', null, 'O ÂNGULO FORMADO ENTRE O VENTO RELATIVO E A LINHA DA CORDA DA ASA DENOMINA-SE ÂNGULO DE', null, '[{"letra": "A", "texto": "diedro", "imagem_url": null}, {"letra": "B", "texto": "ataque", "imagem_url": null}, {"letra": "C", "texto": "incidência", "imagem_url": null}, {"letra": "D", "texto": "atitude", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '179ba8d6-417f-4ec4-b0f9-5a2c829198e0', 'Legislação Aeronáutica', null, 'UMA EMPRESA PODERÁ OPERAR COM UMA TRIPULAÇÃO DE REVEZAMENTO NAS SEGUINTES CONDIÇÕES:', null, '[{"letra": "A", "texto": "voos nacionais e internacionais, com autorização da ANAC, imperiosa necessidade; atrasos devido a problemas de manutenção ou falta de tripulantes", "imagem_url": null}, {"letra": "B", "texto": "por escala, atrasos devido a conexões com voos internacionais para atender outra aeronave que esteja com problemas; com autorização do Comando da Aeronáutica", "imagem_url": null}, {"letra": "C", "texto": "por solicitação do fretante, atrasos devido a extravio de bagagens ou por problemas meteorológicos; com autorização do DECEA", "imagem_url": null}, {"letra": "D", "texto": "Somente em voos internacionais programados", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '17d1145e-990f-45bc-8232-64a4067432c2', 'Conhecimentos Técnicos', null, 'DAS CIRCUNSTÂNCIAS ABAIXO, INDIQUE A QUE PODE SER CONSEQUÊNCIA DE NEVOEIRO', null, '[{"letra": "A", "texto": "redução da visibilidade", "imagem_url": null}, {"letra": "B", "texto": "intensa radiação terrestre", "imagem_url": null}, {"letra": "C", "texto": "umidade relativa moderada", "imagem_url": null}, {"letra": "D", "texto": "turbulência térmica", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '17d2b06d-e4a1-4a58-852d-b209a25755d9', 'Conhecimentos Técnicos', null, 'QUANDO HÁ SUBLIMAÇÃO DO VAPOR DE ÁGUA NA ATMOSFERA, OCORRE A FORMAÇÃO DE:', null, '[{"letra": "A", "texto": "chuva", "imagem_url": null}, {"letra": "B", "texto": "gotículas de água", "imagem_url": null}, {"letra": "C", "texto": "vapor de água", "imagem_url": null}, {"letra": "D", "texto": "cristais de gelo", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '17d4af46-80bd-456e-8e8a-599e5ef3f9ff', 'Legislação Aeronáutica', null, 'A TRANSFERÊNCIA PERMANENTE CARACTERIZA-SE POR:', null, '[{"letra": "A", "texto": "O DESLOCAMENTO DO TRIPULANTE DE SUA BASE, POR PERÍODO MÍNIMO DE 30 DIAS, COM MUDANÇA DE DOMICILIO", "imagem_url": null}, {"letra": "B", "texto": "O DESLOCAMENTO DO TRIPULANTE PARA PRESTAÇÃO DE SERVIÇOS TEMPORÁRIOS", "imagem_url": null}, {"letra": "C", "texto": "O DESLOCAMENTO DO TRIPULANTE DE SUA BASE, POR PERÍODO SUPERIOR A 120 DIAS, COM MUDANÇA DE DOMICÍLIO", "imagem_url": null}, {"letra": "D", "texto": "A MUDANÇA DE DOMICÍLIO POR PERÍODO SUPERIOR A 160 DIAS", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '17ece362-7d34-4e3a-934f-b696a644cfaa', 'Segurança e Emergência', null, 'EM CASO DE TURBULÊNCIA DURANTE OS SERVIÇOS DE ROTINA, OS COMISSÁRIOS DEVEM', null, '[{"letra": "A", "texto": "FAZER A ALOCUÇÃO PERTINENTE, TRAVAR OS TROLLEYS NAS GALLEYS E PERMANECER SENTADOS COM OS CINTOS AFIVELADOS", "imagem_url": null}, {"letra": "B", "texto": "ABRIR COMUNICAÇÃO COM A CABINE DE COMANDO PARA OBTER INFORMAÇÕES SOBRE A SEVERIDADE E TEMPO APROXIMADO DE TURBULÊNCIA (S.T.A.T)", "imagem_url": null}, {"letra": "C", "texto": "PERMANECER AO LONGO DA CABINE PARA ATENDIMENTO AOS PASSAGEIROS", "imagem_url": null}, {"letra": "D", "texto": "OCUPAR OS ASSENTOS PRÓXIMOS A PASSAGEIROS EM PÂNICO E ACALMÁ-LOS", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '17f3cd3f-2908-463d-bedd-cfc3ee1e7f62', 'Legislação Aeronáutica', null, 'O COMANDANTE DA AERONAVE EXERCE A AUTORIDADE QUE LHE É ATRIBUÍDA PELO CBA E POR OUTRAS DISPOSIÇÕES LEGAIS, SOBRE PESSOAS E COISAS EMBARCADAS,', null, '[{"letra": "A", "texto": "desde o momento em que se apresenta para o voo, até aquele em que entrega a aeronave, concluída a viagem", "imagem_url": null}, {"letra": "B", "texto": "dutante toda a etapa do voo, exceto nas escalas", "imagem_url": null}, {"letra": "C", "texto": "ao longo do voo, da decolagem ao pouso, exceto nos pernoites ocasionais", "imagem_url": null}, {"letra": "D", "texto": "unicamente durante o voo, mesmo nas diversas escalas", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '17f5ecdd-b1c1-4f47-9627-7a088a2361a5', 'Primeiros Socorros', null, 'SENSAÇÃO VAGA DE MAL-ESTAR, PALIDEZ, SUDORESE, DISCRETA HIPOTENSÃO, NÁUSEAS E ATÉ VÔMITOS, SÃO SINTOMAS DE:', null, '[{"letra": "A", "texto": "desmaio", "imagem_url": null}, {"letra": "B", "texto": "hipóxia", "imagem_url": null}, {"letra": "C", "texto": "anóxia", "imagem_url": null}, {"letra": "D", "texto": "mal do ar", "imagem_url": null}]'::jsonb, 'D', null),
('anac', '17fef65c-7ac2-4e27-a2bb-75ed854649b6', 'Conhecimentos Técnicos', null, 'O TIPO DE GELO MAIS QUEBRADIÇO E DE DISSIPAÇÃO MAIS FÁCIL É O:', null, '[{"letra": "A", "texto": "opaco", "imagem_url": null}, {"letra": "B", "texto": "claro", "imagem_url": null}, {"letra": "C", "texto": "de bandeja", "imagem_url": null}, {"letra": "D", "texto": "granizo", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '18032fa3-ca2e-4826-b972-52aaf29c884e', 'Primeiros Socorros', null, 'À TEMPERATURA CONSTANTE, OS VOLUMES OCUPADOS POR UMA MESMA MASSA GASOSA SÃO INVERSAMENTE PROPORCIONAIS ÀS PRESSÕES QUE SUPORTAM. ESTA AFIRMATIVA É, BASICAMENTE, O ENUNCIADO DA LEI DE', null, '[{"letra": "A", "texto": "HUME", "imagem_url": null}, {"letra": "B", "texto": "BOYLE", "imagem_url": null}, {"letra": "C", "texto": "DALTON", "imagem_url": null}, {"letra": "D", "texto": "GAY-LUSSAC", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '180337e8-4af6-4b60-aeb9-ff04d88bd696', 'Legislação Aeronáutica', null, 'O NÚMERO MÁXIMO DE PERÍODOS TRABALHADOS PODE SER ESTENDIDO EM 36 HORAS, NO CASO DE:', null, '[{"letra": "A", "texto": "problemas de manutenção", "imagem_url": null}, {"letra": "B", "texto": "necessidade de escala", "imagem_url": null}, {"letra": "C", "texto": "No caso de voos internacionais de longo curso", "imagem_url": null}, {"letra": "D", "texto": "condições meteorológicas", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '1819428c-35a2-4418-86db-099326ffa814', 'Legislação Aeronáutica', null, 'CASO O TRANSPORTADOR VENHA A CANCELAR A VIAGEM, O PASSAGEIRO', null, '[{"letra": "A", "texto": "poderá ser ressarcido, em valor equivalente ao dobro do que foi pago pelo bilhete", "imagem_url": null}, {"letra": "B", "texto": "terá direito ao reembolso do valor já pago da passagem", "imagem_url": null}, {"letra": "C", "texto": "será hospedado em hotel, por tempo indeterminado", "imagem_url": null}, {"letra": "D", "texto": "receberá, como bônus, uma passagem para outro trecho", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '18248d72-ebb5-46f3-859c-ff836273a2b7', 'Legislação Aeronáutica', null, 'É O DOCUMENTO EXPEDIDO PELA ANAC, APÓS A COMPROVAÇÃO EXIGIDA PARA A HABILITAÇÃO NO EQUIPAMENTO PRETENDIDO, INFORMA E COMPROVA QUE O AERONAUTA ESTÁ HABILITADO A TRIPULAR AQUELA AERONAVE, FAZENDO REFERÊNCIA AO EQUIPAMENTO', null, '[{"letra": "A", "texto": "CERTIFICADO DE CAPACIDADE FISICA", "imagem_url": null}, {"letra": "B", "texto": "CERTIFICADO DE RESPONSABILIDADE AEREA", "imagem_url": null}, {"letra": "C", "texto": "CERTIFICADO DE HABILITAÇÃO TECNICA", "imagem_url": null}, {"letra": "D", "texto": "LICENÇA DE VOO", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '18285b8e-3849-4acc-a75a-a0525eaacbfa', 'Legislação Aeronáutica', null, 'O NÚMERO DE FOLGAS A QUE UM TRIPULANTE DE EMPRESA AÉREA REGULAR, QUE CONCORRER POR 15 DIAS À ESCALA DE SERVIÇO DO MÊS, POR MOTIVO DE FÉRIAS OU AFASTAMENTO TERÁ DIREITO A QUANTAS FOLGAS NESTE PERÍODO?', null, '[{"letra": "A", "texto": "10", "imagem_url": null}, {"letra": "B", "texto": "6", "imagem_url": null}, {"letra": "C", "texto": "5", "imagem_url": null}, {"letra": "D", "texto": "8", "imagem_url": null}]'::jsonb, 'C', null),
('anac', '1832709c-4bd4-410b-bbda-6a05cb1b0036', 'Legislação Aeronáutica', null, 'A SIMPLIFICAÇÃO DAS FORMALIDADES ADUANEIRAS, DE IMIGRAÇÃO E SAÚDE PÚBLICA, NO QUE SE REFERE AO TRÁFEGO AÉREO INTERNACIONAL, BEM COMO O TRATAMENTO DOS MÚLTIPLOS ASPECTOS ECONÔMICOS DO TRÁFEGO AÉREO, FOI CONSEGUIDO PELA:', null, '[{"letra": "A", "texto": "IATA", "imagem_url": null}, {"letra": "B", "texto": "OACI", "imagem_url": null}, {"letra": "C", "texto": "CLAC", "imagem_url": null}, {"letra": "D", "texto": "ALTA", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '18441f04-a95e-4179-a036-9633dff3e685', 'Primeiros Socorros', null, 'A CONDUTA EM CASO DA PRESENÇA DE CORPOS ESTRANHOS ENCRAVADOS É NÃO RETIRÁ-LO PORQUE:', null, '[{"letra": "A", "texto": "diminui a lesão e não atinge tecidos vizinhos como vasos e nervos", "imagem_url": null}, {"letra": "B", "texto": "aumenta a lesão podendo levar o indivíduo ao choque", "imagem_url": null}, {"letra": "C", "texto": "não ocorre alteração e o enunciado está incorreto", "imagem_url": null}, {"letra": "D", "texto": "aumenta a lesão e o indivíduo poderá sofrer um mal súbito e necessitar de avaliação mais apurada", "imagem_url": null}]'::jsonb, 'A', null),
('anac', '1850893c-cd97-4248-a76a-e5214da54e7a', 'Primeiros Socorros', null, 'A HEMORRAGIA EXTERNA QUE SE APRESENTA EM JATOS, DE COR VERMELHO VIVO, PODENDO CONTER BOLHAS, SÃO CARACTERÍSTICAS DA PERDA DE SANGUE', null, '[{"letra": "A", "texto": "VENOSA", "imagem_url": null}, {"letra": "B", "texto": "BASAL", "imagem_url": null}, {"letra": "C", "texto": "CAPILAR", "imagem_url": null}, {"letra": "D", "texto": "ARTERIAL", "imagem_url": null}]'::jsonb, 'D', null),
