('anac', '188942bb-e727-4b0b-a71a-b6251f2f810b', 'Legislação Aeronáutica', null, 'ENTRE OS BENEFÍCIOS DA PREVIDÊNCIA, O AUXÍLIO DOENÇA É PAGO AO ACIDENTADO QUE FICAR INCAPACITADO PARA O  TRABALHO. ESTE BENEFÍCIO SERÁ PAGO AO SEGURADO AFASTADO DO SERVIÇO, A PARTIR DE:', null, '[{"letra": "A", "texto": "13 dias", "imagem_url": null}, {"letra": "B", "texto": "07 dias", "imagem_url": null}, {"letra": "C", "texto": "16 dias", "imagem_url": null}, {"letra": "D", "texto": "25 dias", "imagem_url": null}]'::jsonb, 'C', null),
