('anac', '26a4fff1-3dc0-418f-b25e-dd818c7e37aa', 'Primeiros Socorros', null, 'A INCIDÊNCIA, EM CURTO PERÍODO DE TEMPO, DE UM GRANDE NÚMERO DE CASOS DE UMA DETERMINADA DOENÇA, EM UMA DADA REGIÃO, É A DEFINIÇÃO DE', null, '[{"letra": "A", "texto": "PANDEMIA", "imagem_url": null}, {"letra": "B", "texto": "EPIDEMIA", "imagem_url": null}, {"letra": "C", "texto": "SURTO", "imagem_url": null}, {"letra": "D", "texto": "PESTE", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '26b3ae68-51bf-4d3d-a4bb-4578d074a2c2', 'Segurança e Emergência', null, 'NUMA SOBREVIVÊNCIA EM TERRA, COM RELAÇÃO AO VESTUÁRIO, DEVE-SE:', null, '[{"letra": "A", "texto": "usar pouca roupa, principalmente quando chover, assim evita-se de ficar a com a mesma úmida, prevenindo-se de doenças respiratórias", "imagem_url": null}, {"letra": "B", "texto": "estar vestido sempre com o mínimo de roupa possível, mesmo à noite, devido o excesso de vapor conservado na superfície", "imagem_url": null}, {"letra": "C", "texto": "usar o máximo de roupa possível, protegendo-se todo o corpo, inclusive extremidade e rosto", "imagem_url": null}, {"letra": "D", "texto": "usar o mínimo de roupa possível quando fizer sol, evitando-se o excesso de transpiração", "imagem_url": null}]'::jsonb, 'C', null)
