('anac', '335c8357-accd-4ac6-bc1c-32bc3a059359', 'Segurança e Emergência', null, 'EM CASO DE INCÊNDIO A BORDO, HAVENDO FUMAÇA DENSA NA CABINE, A MELHOR MANEIRA DE SE DESLOCAR RUMO A SAÍDA DE EMERGÊNCIA SERÁ:', null, '[{"letra": "A", "texto": "andando normalmente, pois nas partes mais altas existe mais oxigênio", "imagem_url": null}, {"letra": "B", "texto": "andando agachado, protegendo os olhos e o nariz", "imagem_url": null}, {"letra": "C", "texto": "arrastando-se pelo chão, pois junto a este permanece uma camada de ar menos contaminada", "imagem_url": null}, {"letra": "D", "texto": "arrastando-se pelo chão, porém mantendo a cabeça erguida, pois junto ao mesmo existe mais fumaça", "imagem_url": null}]'::jsonb, 'C', null),
