('anac', '3c112954-90cd-4faa-a4ff-a6a070cb323c', 'Primeiros Socorros', null, 'APÓS UM ACIDENTE, CASO UM PASSAGEIRO APRESENTE UMA FRATURA NO ANTEBRAÇO, O SOCORRISTA DEVERÁ', null, '[{"letra": "A", "texto": "PROTEGER A REGIÃO LESADA, APENAS COM UM PANO EM FORMA DE TIPOIA", "imagem_url": null}, {"letra": "B", "texto": "PROTEGER O LOCAL COM UM PANO, COLOCANDO TALAS AMARRADAS COM TIRAS, ACIMA E ABAIXO DA LESÃO, USANDO UMA TIPOIA", "imagem_url": null}, {"letra": "C", "texto": "ESTICAR BEM TODO O BRAÇO E IMOBILIZÁ-LO DESTA MANEIRA, COM TALAS IMPROVISADAS, EVITANDO LESÕES NO COTOVELO", "imagem_url": null}, {"letra": "D", "texto": "ENCOSTAR O ANTEBRAÇO ESTICADO JUNTO AO PEITO E ENFAIXÁ-LO, ENROLANDO TODO O DORSO PARA TOTAL IMOBILIZAÇÃO", "imagem_url": null}]'::jsonb, 'B', null),
('anac', '3c115123-8e6d-4c7c-81e2-9bfd3c3cfe9e', 'Segurança e Emergência', null, 'AO SE MONTAR UMA FOGUEIRA, PARA SE CONSEGUIR O MÁXIMO DE CALOR E PROTEÇÃO DO FOGO, DEVE-SE ARMÁ-LA', null, '[{"letra": "A", "texto": "NO MEIO DE ARBUSTOS PARA QUE O VENTO NÃO A APAGUE", "imagem_url": null}, {"letra": "B", "texto": "PRÓXIMO A UMA ROCHA OU A UM MURO FEITO DE TRONCOS", "imagem_url": null}, {"letra": "C", "texto": "JUNTO AOS DESTROÇOS DA AERONAVE, PARA SE APROVEITAR O SEU COMBUSTÍVEL", "imagem_url": null}, {"letra": "D", "texto": "NO MEIO DO ACAMPAMENTO, POIS AS PESSOAS SERVIRÃO DE PROTEÇÃO", "imagem_url": null}]'::jsonb, 'B', null),
