('anac', '3c1dd785-5f65-47fb-b7f0-c48dfe7d761e', 'Primeiros Socorros', null, 'A SE REALIZAR A MASSAGEM CARDIO-RESPIRATÓRIA (RCP), OBJETIVA-SE:', null, '[{"letra": "A", "texto": "oxigenação e circulação sanguínea até a chegada dos médicos", "imagem_url": null}, {"letra": "B", "texto": "oxigenar os pulmões e estimulação sanguínea", "imagem_url": null}, {"letra": "C", "texto": "levar monóxido de carbono porque estimula o cérebro", "imagem_url": null}, {"letra": "D", "texto": "injetar gás carbônico porque estimula o pulmão", "imagem_url": null}]'::jsonb, 'A', null),
