('anac', '3c32d47e-d59c-4607-b5a6-3c6691a17fbd', 'Primeiros Socorros', null, 'ASSINALE A ALTERNATIVA CORRETA:', null, '[{"letra": "A", "texto": "se a vítima apresenta rigor-mortis, iniciar reanimação cardio-pulmonar", "imagem_url": null}, {"letra": "B", "texto": "o socorro eficiente deverá ocorrer, preferencialmente, antes do 4° minuto em que o indivíduo se encontra em parada cardio-respiratória", "imagem_url": null}, {"letra": "C", "texto": "em recém-nascidos não deve-se fazer manobra reanimatória, pois as estruturas corporais são pequenas demais", "imagem_url": null}, {"letra": "D", "texto": "deve-se realizar a reanimação cardio-pulmonar sempre, desde que tenhamos certeza da hora em que ocorreu", "imagem_url": null}]'::jsonb, 'B', null),
